void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec3 color_X = vec3(1.0, 0.0, 0.0); // Red for player X
    vec3 color_O = vec3(0.0, 0.0, 1.0); // Blue for player O
    float s = min(iResolution.x, iResolution.y);
    if (fragCoord.x > s || fragCoord.y > s)
    {
        fragColor = vec4(vec3(0.0), 1.0);
        return;
    }
    vec2 st = (fragCoord + vec2(0.0 * s, 0.0)) / s;

    vec2 tmp = floor(st * vec2(3.0));
    ivec2 tileIDX = ivec2(floor(st * vec2(3.0)));
    st = tile(st, 3.0, 3.0);


    int play = board[tileIDX.x + ((2-tileIDX.y) * 3)];
    vec3 color = (tileIDX.x+tileIDX.y)%2 ==0? vec3(1.0): vec3(.5);

    color= play==1 ? mix(color, color_X , player_X(st, 0.3)) : mix(color, color_O ,player_O(st, 0.1)) ;
    fragColor = vec4(color, 1.0f);
}

mat2x2 rotate2d(float theta)
{
    return mat2x2(cos(theta), -sin(theta), sin(theta), cos(theta));
}

vec2 tile(vec2 st, float row, float col)
{
    return fract(st * vec2(row, col));
}
float rect(vec2 st, vec2 size)
{
    size = 0.25 * (1.0 - size);
    float AA = 0.001;

    vec2 uv = smoothstep(size, size + AA, st * (1.0 - st));

    return uv.x * uv.y;
}



float draw_cross(in vec2 st, float size, float thickness) {
    return step(0.5, rect(st, vec2(size, size / thickness)) +
            rect(st, vec2(size / thickness, size)));
}

float player_O(vec2 st, float r)
{
    vec2 l = st - vec2(0.5);

    return (1.0 - smoothstep(r, r + 0.02, dot(l, l) * 2.)) * (smoothstep(r / 2., r / 2. + 0.02, dot(l, l) * 2.));
}
float player_X(vec2 st, float s)
{
    st -= 0.5;
    st = rotate2d(acos(-1.0) / 4.0) * st;

    st += 0.5;
    return draw_cross(st, 0.2, 16.);
}

const int board[9] = int[](
        0, 0, 1,
        1, 1, 0,
        0, 1, 1
    );
